assume(b > 0)
assume(p > 0)
assume(n > 0)
assume(e > 0)
assume(c > 0)
assume(d > 0)
assume(a > 0)
assume(f > 0)
assume(m > 0)
from sage.interfaces.expect import Expect
giac.eval('threads:=1')
Expect._eval_line(giac, 'casbench_F:="casbench_unset":;', allow_use_file=False)
t0 = walltime()
try:
    _casbench_integrand = (((((e+(f*x)))^(m)*(cos((c+(d*x))))^(p))*(sin((c+(d*x))))^(n))*((a+(b*sin((c+(d*x))))))^((-1)))
    _casbench_gf = giac(_casbench_integrand)
    _casbench_out = Expect._eval_line(giac, 'casbench_F:=int(' + _casbench_gf.name() + ',' + str(giac(x)) + '):;', allow_use_file=False)
    t1 = walltime()
    _casbench_failed = [l for l in _casbench_out.splitlines() if 'Error:' in l]
    if _casbench_failed: raise RuntimeError('giac: ' + ' | '.join(_casbench_failed))
    if Expect._eval_line(giac, 'type(casbench_F)', allow_use_file=False).strip().splitlines()[-1] == 'string':
        raise RuntimeError('giac gave no antiderivative: ' + ' '.join(_casbench_out.split())[:600])
    _casbench_giac_answer = giac('casbench_F')
    _casbench_giac_text = str(_casbench_giac_answer)
    _casbench_expr = [l for l in _casbench_giac_text.splitlines() if not l.startswith(('Simplification assuming', 'Warning', 'Check ['))]
    if any('integrate(' in l for l in _casbench_expr):
        _casbench_answer = _casbench_integrand.integrate(x, hold=True)
    else:
      try:
        _casbench_answer = _casbench_giac_answer.sage()
      except Exception as ex:
        _casbench_msgs = [l for l in _casbench_giac_text.splitlines() if l.startswith(('Simplification assuming', 'Warning', 'Check ['))]
        if _casbench_msgs: raise RuntimeError('answer unreadable through the Sage interface: Giac reprints messages each time it is evaluated (' + _casbench_msgs[0] + ')')
        _casbench_answer = _casbench_giac_text
except Exception as ex:
    import sys
    print('casbench sage_error:', repr(ex), file=sys.stderr)
    print('<<' + 'ANS>>', 'sage_error: ' + type(ex).__name__ + ': ' + ' '.join(str(ex).split())[:1500])
    print('<<' + 'TIME>>', walltime() - t0)
    raise SystemExit(0)
