    _casbench_integrand = ((((a+(b*tan((e+(f*x))))))^(1/2)*(A+(B*tan((e+(f*x))))))*(((c+(d*tan((e+(f*x))))))^(1/2))^((-1)))
    _casbench_gf = giac(_casbench_integrand)
